document.documentElement.classList.add("js");const toggle=document.querySelector(".nav-toggle"),menu=document.getElementById("mobile-menu");if(toggle&&menu&&(toggle.addEventListener("click",()=>{const e=menu.classList.toggle("is-open");toggle.setAttribute("aria-expanded",String(e))}),menu.addEventListener("click",e=>{e.target.closest("a")&&(menu.classList.remove("is-open"),toggle.setAttribute("aria-expanded","false"))})),"IntersectionObserver"in window){const e=new IntersectionObserver(t=>{for(const s of t)s.isIntersecting&&(s.target.classList.add("is-visible"),e.unobserve(s.target))},{rootMargin:"0px 0px -8% 0px"});document.querySelectorAll(".reveal").forEach(t=>e.observe(t))}else document.querySelectorAll(".reveal").forEach(e=>e.classList.add("is-visible"));
